property.value:

let $allowedNumbers := tokenize('0,1,-1', ',')
return (
	//LiteralExpression[
		@String = false()
		and @Null = false()
		and (@LiteralType = 'INTEGER' or @LiteralType = 'LONG' or @LiteralType = 'DECIMAL' or @LiteralType = 'DOUBLE')
		and not(@Image = $allowedNumbers)
		and not(ancestor::ArrayLoadExpression)
		and not(ancestor::FieldDeclarationStatements[ModifierNode[@Static = true() and @Final = true()]])
		and not(ancestor::StandardCondition[parent::ForLoopStatement or parent::WhileLoopStatement or parent::DoLoopStatement])
		and not(
			parent::BooleanExpression[@Op = ('==', '!=', '<', '<=', '>', '>=')]
			and (
				@Image = $allowedNumbers
				or exists(../LiteralExpression[@Image = $allowedNumbers])
			)
		)
		and not(
			ancestor::UserClass[
				let $isTestAnnot := .//Annotation[lower-case(@Image) = 'istest' or lower-case(@Name) = 'istest']
				return exists($isTestAnnot)
					and (
						not($isTestAnnot/AnnotationParameter[lower-case(@Name) = 'seealldata'])
						or $isTestAnnot/AnnotationParameter[lower-case(@Name) = 'seealldata' and lower-case(@Value) = 'false']
						or $isTestAnnot/AnnotationParameter[lower-case(@Name) = 'seealldata' and lower-case(@Image) = 'false']
					)
			]
		)
	]
)

rule.example:

// Violation: Magic numbers in calculations
Integer total = price * 1.15;  // ❌ What is 1.15?
Integer timeout = 30000;  // ❌ What is 30000?
Decimal discount = amount * 0.10;  // ❌ What is 0.10?

// Valid: Use named constants
private static final Decimal TAX_RATE = 1.15;
private static final Integer TIMEOUT_MS = 30000;
private static final Decimal DISCOUNT_PERCENTAGE = 0.10;

Integer total = price * TAX_RATE;
Integer timeout = TIMEOUT_MS;
Decimal discount = amount * DISCOUNT_PERCENTAGE;


// Valid: Common "safe" numbers (0, 1, -1) are allowed
Integer count = 0;
Integer index = 1;
Integer offset = -1;
if (value > 0) { }
if (size == 1) { }
if (result != -1) { }


// Valid: Array/list indices are allowed
List<String> items = new List<String>();
String first = items[0];
String second = items[1];
Integer value = array[2];


// Valid: Loop conditions are allowed
for (Integer i = 0; i < 10; i++) { }
for (Integer j = 0; j < items.size(); j++) { }
while (count < 100) { }
do { } while (index < 5);


// Valid: Comparisons with safe numbers (0, 1, -1) are allowed
if (count == 0) { }
if (size > 1) { }
if (result != -1) { }
if (value < 0) { }


// Valid: Test classes with @IsTest are exempt (SeeAllData defaults to false)
@IsTest
private class TestClassDefault {
    static void testMethod() {
        // Magic numbers are allowed in test classes (SeeAllData=false by default)
        Integer batchSize = 200;  // ✅ Allowed
        Decimal taxRate = 0.08;   // ✅ Allowed
        Account acc = new Account(AnnualRevenue = 50000); // ✅ Allowed
        System.assertEquals(3, records.size()); // ✅ Allowed
    }
}

// Valid: Test classes with @IsTest(SeeAllData=false) are exempt
@IsTest(SeeAllData=false)
private class TestClassExplicitFalse {
    static void testMethod() {
        // Magic numbers are allowed when SeeAllData=false
        Integer timeout = 30000;  // ✅ Allowed
        Decimal discount = amount * 0.10;  // ✅ Allowed
    }
}

// Regular classes still require constants for magic numbers
public class MyRegularClass {
    private static final Integer BATCH_SIZE = 200;
    private static final Decimal TAX_RATE = 0.08;

    public void processData() {
        Integer batchSize = BATCH_SIZE;  // ✅ Use constants
        // ...
    }
}
